@dataclass
class Step:
    """**One forecast bar.** `close` always; `open`, `high`, `low` where the model gives them."""

    close: float
    # Intervals around the step, each lo ≤ hi with its probability p in (0, 1).
    bands: Optional[List[Band]] = None
    # When the step is expected to close, UTC ms — needed where the form's interval has no fixed length (a month).
    expected_ms: Optional[int] = None
    high: Optional[float] = None
    low: Optional[float] = None
    open: Optional[float] = None
    # Quantiles of the close by their level ("0.05": 1.0921, "0.5": 1.0956, …), each level in (0, 1).
    quantiles: Optional[Dict[str, float]] = None
    # Sampled closes, drawn as paths or folded into an empirical band.
    samples: Optional[List[float]] = None
    volume: Optional[float] = None

    @classmethod
    def from_dict(cls, d: Dict[str, Any]) -> "Step":
        return cls(
            close=d["close"],
            bands=(None if d.get("bands") is None else [Band.from_dict(_x0) for _x0 in d.get("bands")]),
            expected_ms=d.get("expected_ms"),
            high=d.get("high"),
            low=d.get("low"),
            open=d.get("open"),
            quantiles=(None if d.get("quantiles") is None else {_k0: _v0 for _k0, _v0 in d.get("quantiles").items()}),
            samples=(None if d.get("samples") is None else [_x0 for _x0 in d.get("samples")]),
            volume=d.get("volume"),
        )

    def to_dict(self) -> Dict[str, Any]:
        d: Dict[str, Any] = {}
        d["close"] = _plain(self.close)
        if self.bands is not None:
            d["bands"] = _plain(self.bands)
        if self.expected_ms is not None:
            d["expected_ms"] = _plain(self.expected_ms)
        if self.high is not None:
            d["high"] = _plain(self.high)
        if self.low is not None:
            d["low"] = _plain(self.low)
        if self.open is not None:
            d["open"] = _plain(self.open)
        if self.quantiles is not None:
            d["quantiles"] = _plain(self.quantiles)
        if self.samples is not None:
            d["samples"] = _plain(self.samples)
        if self.volume is not None:
            d["volume"] = _plain(self.volume)
        return d


@dataclass
class WindowPlace:
    """A `WindowPlace` as the catalogue describes it."""

    # The chart's uri.
    chart: str
    # Its rectangle as fractions of the chart area: [x0, y0, x1, y1], each 0..1, x0 < x1, y0 < y1.
    rect: List[float]

    @classmethod
    def from_dict(cls, d: Dict[str, Any]) -> "WindowPlace":
        return cls(
            chart=d["chart"],
            rect=[_x0 for _x0 in d["rect"]],
        )

    def to_dict(self) -> Dict[str, Any]:
        d: Dict[str, Any] = {}
        d["chart"] = _plain(self.chart)
        d["rect"] = _plain(self.rect)
        return d


@dataclass
class WindowShape:
    """**What a model reads, written once and shared**: the markets, the frames, the interval whose closes cut a
    window, how many closed bars each frame holds, and how many bars of that interval after the close a training
    target holds. `bars_window` answers one such window; `extract_windows` writes one at every close of a span.
    """

    # The markets, 1 to 64, each one of the workbench's.
    symbols: List[str]
    # The frames, 1 to 16: intervals' labels.
    frames: List[str]
    # The interval whose closes cut a window: one window at each close.
    interval: str
    # Closed bars per frame per market in each window, 1 to 5000.
    lookback: int
    # Bars of the interval after the close, of the first market, written as the window's target; 0 for none.
    target_steps: Optional[int] = None

    @classmethod
    def from_dict(cls, d: Dict[str, Any]) -> "WindowShape":
        return cls(
            symbols=[_x0 for _x0 in d["symbols"]],
            frames=[_x0 for _x0 in d["frames"]],
            interval=d["interval"],
            lookback=d["lookback"],
            target_steps=d.get("target_steps"),
        )

    def to_dict(self) -> Dict[str, Any]:
        d: Dict[str, Any] = {}
        d["symbols"] = _plain(self.symbols)
        d["frames"] = _plain(self.frames)
        d["interval"] = _plain(self.interval)
        d["lookback"] = _plain(self.lookback)
        if self.target_steps is not None:
            d["target_steps"] = _plain(self.target_steps)
        return d


class _AccountApi:
    """The `account` capabilities."""

    def __init__(self, client: _Client) -> None:
        self._c = client

    def fills_get(self, account: str) -> Dict[str, Any]:
        """Answers the measurement fills_measure started: whether it is still reading, the laboratory it re-prices on, per market the shortfall's figures and the calibrated slippage (fixed at the median, random up to twice the mean, each in the market's price units), the latency, and every deal re-priced.

        Scope: read. Plan: free. Since: 1.14.0.
        Arguments:
            account: The account's uri, as get_state gives it: bentrix://account/<id>.
        """
        return _identity(self._c.call("fills_get", {"account": account}, {}))

    def fills_make_bench(self, account: str, *, alike: Optional[str] = None, latency: Optional[bool] = None, slippage: Optional[str] = None) -> Dict[str, Any]:
        """Makes a laboratory workbench alike one of the account's history's laboratory, its fills slipping by what fills_measure measured — fixed at the median or random with the measured mean, each market in its own price units — and waiting the measured latency where chosen; a strategy re-run there runs on the person's own slippage. Answers the workbench's uri.

        Scope: lab. Plan: free. Since: 1.14.0.
        Arguments:
            account: The account's uri, as get_state gives it: bentrix://account/<id>.
            alike: The laboratory workbench to make it alike (the laboratory's first when absent): bentrix://lab/<lab>/bench/<bench>.
            latency: Whether the measured latency is taken too (true when absent).
            slippage: median (fixed at each market's median shortfall) or mean (random, its mean the measured mean); median when absent.
        """
        return _identity(self._c.call("fills_make_bench", {"account": account}, {"alike": alike, "latency": latency, "slippage": slippage}))

    def fills_measure(self, account: str, *, span: Optional[str] = None) -> Dict[str, Any]:
        """Reads a real account's deals and orders off its MetaTrader (prices and moments, no money figure) and re-prices each on the laboratory of that account's history: per market the shortfall against what Bentrix's venue would have filled (median, mean, 90th percentile, worst, in points), the latency from placing a market order to its fill, and a calibrated slippage. Starts the read and answers as fills_get does; fills_get again until reading is false.

        Scope: read. Plan: free. Since: 1.14.0.
        Arguments:
            account: The account's uri, as get_state gives it: bentrix://account/<id>.
            span: How far back: 30d, 90d, 1y or all (90d when absent).
        """
        return _identity(self._c.call("fills_measure", {"account": account}, {"span": span}))


