class _AgentApi:
    """The `agent` capabilities."""

    def __init__(self, client: _Client) -> None:
        self._c = client

    def release(self) -> Dict[str, Any]:
        """Pauses every strategy run this agent started that still runs, and disarms the automation of the workbenches they ran on — everything else stays as it is. Answers what was let go.

        Scope: lab. Plan: plus. Since: 1.0.0.
        """
        return _identity(self._c.call("agent_release", {}, {}))

    def whoami(self) -> Dict[str, Any]:
        """This agent's name as its client gave it, the scopes the person granted it on Settings › Agents, the catalogue's version, and whether it is answered while the window is minimized.

        Scope: read. Plan: free. Since: 1.0.0.
        """
        return _identity(self._c.call("agent_whoami", {}, {}))

    def describe(self, name: str) -> Dict[str, Any]:
        """One tool as the catalogue declares it: its title, description, scope, tier, the version it arrived in, and its arguments' and answer's schemas.

        Scope: read. Plan: free. Since: 1.0.0.
        Arguments:
            name: A tool's name.
        """
        return _identity(self._c.call("describe", {"name": name}, {}))

    def feedback_report(self, queue: Literal["need", "bug"], text: str) -> _Job[Dict[str, Any]]:
        """Sends a bug the agent found, or a need it has, to Bentrix's intake itself, exactly as the report window's Send does - the same queue (bug or need), the same install id, build, platform and moment, no account - with a first line naming the agent; the person is not asked first, and the agent's log keeps the text sent. At most 5 an hour from one agent. Answers a job: completed when the intake took it, failed with why when it did not arrive.

        Scope: lab. Plan: free. Since: 1.22.0.
        Arguments:
            text: The report, in the agent's own words: what it did, what it saw, what it expected. Sent as it is, under a first line naming the agent; no person reads it before it leaves.
        """
        return self._c.call_job("feedback_report", {"queue": queue, "text": text}, {}, _identity)

    def feedback_send(self, queue: Literal["need", "bug"], text: str) -> _Job[Dict[str, Any]]:
        """Opens Bentrix's report window filled with this text, in the need or bug queue; the person sends it or closes it. Answers a job: completed when it is sent, failed when it was closed unsent or did not arrive.

        Scope: lab. Plan: free. Since: 1.0.0.
        Arguments:
            text: The report, in the agent's words; the person reads it before it is sent.
        """
        return self._c.call_job("feedback_send", {"queue": queue, "text": text}, {}, _identity)

    def job_cancel(self, job: str) -> Dict[str, Any]:
        """Withdraws a question this agent asked that the person has not answered: a card is taken away; a sheet or window the person has open stays theirs. Answers the job.

        Scope: lab. Plan: free. Since: 1.0.0.
        Arguments:
            job: The job's handle, as the tool that started it answered.
        """
        return _identity(self._c.call("job_cancel", {"job": job}, {}))

    def job_get(self, job: str) -> Dict[str, Any]:
        """Answers a job this agent started: awaiting_person, completed with its result, failed with the reason, or cancelled.

        Scope: read. Plan: free. Since: 1.0.0.
        Arguments:
            job: The job's handle, as the tool that started it answered.
        """
        return _identity(self._c.call("job_get", {"job": job}, {}))

    def job_list(self) -> Dict[str, Any]:
        """Answers every job this agent started this sitting, each as job_get answers it.

        Scope: read. Plan: free. Since: 1.0.0.
        """
        return _identity(self._c.call("job_list", {}, {}))

    def journal_note(self, bench: str, text: str) -> Dict[str, Any]:
        """Writes one line in a workbench's Journal and Bentrix's log, after this agent's own name, as a run's lines are written.

        Scope: lab. Plan: plus. Since: 1.0.0.
        Arguments:
            bench: The workbench's uri.
        """
        return _identity(self._c.call("journal_note", {"bench": bench, "text": text}, {}))

    def resource_list(self, *, prefix: Optional[str] = None) -> Dict[str, Any]:
        """Answers every resource and stream template this application serves, with its name, title, whether it is a stream and whether it pages, as resources/templates/list gives them; prefix keeps the templates that start with it.

        Scope: read. Plan: free. Since: 1.0.0.
        Arguments:
            prefix: Only the templates that start with this, such as bentrix://{home}/{owner}/bench.
        """
        return _identity(self._c.call("resource_list", {}, {"prefix": prefix}))

    def resource_read(self, uri: str) -> Dict[str, Any]:
        """Answers the same content resources/read gives for a uri, for a client that does not surface resources: the workspace, a workbench, its book, its bars, ticks, quotes, deals and Journal, the screen, the logs, a run. resource_list names them.

        Scope: read. Plan: free. Since: 1.0.0.
        Arguments:
            uri: A resource's URI, as resources/read takes it, its query included.
        """
        return _identity(self._c.call("resource_read", {"uri": uri}, {}))

    def search(self, text: str) -> Dict[str, Any]:
        """The tools whose name, title or description holds every word given, each with its title and the scope it needs.

        Scope: read. Plan: free. Since: 1.0.0.
        Arguments:
            text: Words looked for in a tool's name, title and description.
        """
        return _identity(self._c.call("search", {"text": text}, {}))

    def tool_describe(self, name: str) -> Dict[str, Any]:
        """Answers one tool's whole declaration as tools/list gives it - its description, inputSchema, outputSchema, annotations and _meta - for a client that listed the tools brief (_meta bentrix/brief on tools/list). A tool this agent's scopes do not reach is answered as one that does not exist.

        Scope: read. Plan: free. Since: 1.22.0.
        Arguments:
            name: The tool's name, as tools/list names it.
        """
        return _identity(self._c.call("tool_describe", {"name": name}, {}))

    def wait_for(self, uri: str, *, after: Optional[str] = None, timeout_ms: Optional[int] = None) -> Page:
        """Answers a stream's items since after, waiting up to timeout_ms (at most 60000) for one when there is none yet: the same page subscriptions deliver, for a client that holds no stream. next is the cursor to pass as after.

        Scope: read. Plan: free. Since: 1.0.0.
        Arguments:
            uri: A stream's URI, without its cursor: bentrix://lab/1/bench/2/quotes, bentrix://alerts/log. A stream that takes parameters keeps them in its query (…/closed/window?frames=M15,H1); after is never one of them.
            after: The cursor the last page answered as next; omitted, only what is new.
            timeout_ms: How long to wait for something new, at most 60000 ms; 30000 when omitted.
        """
        return Page.from_dict(self._c.call("wait_for", {"uri": uri}, {"after": after, "timeout_ms": timeout_ms}))

    def log(self, agent: str, *, after: Optional[str] = None, timeout_ms: int = 30000) -> Iterator[Any]:
        """Each tool call an agent made this sitting, oldest first, at most 1000 a page: when, the tool, the scope it asked (a trading act: the workbench's area's), the outcome (ok, bad_arguments, not_found, refused) and the refusal's sentence, and for a trading act what it asked and what it was answered. An agent reads its own; a token holding admin any. next is the last row's seq. Kept for the sitting, at most 5000 rows across agents.

        Scope: read. Plan: free. Since: 1.22.0.
        Arguments:
            agent: The agent's pairing, as agent_whoami and Settings › Agents name it.
            after: the cursor to read since; omitted, only what is new is yielded.
            timeout_ms: how long one wait lasts before it asks again.
        """
        return self._c.watch("bentrix://agents/{agent}/log{?after}", {"agent": agent}, {}, _identity, after, timeout_ms)


