class _ModelApi:
    """The `model` capabilities."""

    def __init__(self, client: _Client) -> None:
        self._c = client

    def check(self, file: str) -> Dict[str, Any]:
        """Reads an ONNX model's folder in the models folder - its manifest checked, its operator census read (a custom operator domain refused before anything loads, an operator the built-in engine lacks said with its offers), the model loaded by the built-in engine for the input the manifest describes and run once on zeros - and answers the manifest, the input's length, the output's length, the engine and the census, or why it would not run. Nothing is started.

        Scope: read. Plan: free. Since: 3.4.0.
        Arguments:
            file: An ONNX model's folder in the models folder.
        """
        return _identity(self._c.call("model_check", {"file": file}, {}))

    def forget(self, name: str) -> Dict[str, Any]:
        """Removes a model an agent installed from the models folder - its files and its record. A model the person put there is the person's own to delete, and is refused here.

        Scope: admin. Plan: free. Since: 3.6.0.
        Arguments:
            name: A model's name in the models folder.
        """
        return _identity(self._c.call("model_forget", {"name": name}, {}))

    def infer(self, name: str, input: List[float]) -> Dict[str, Any]:
        """Runs an ONNX model of the models folder on one input - the Gym's policy run by Bentrix (engine "bentrix") instead of the program's own runtime - consent checked, on the engine the person chose and in its host, the host kept for the next call. Answers its output values and how long it took.

        Scope: lab. Plan: free. Since: 3.6.0.
        Arguments:
            name: An ONNX policy's folder in the models folder: model.onnx, no manifest needed.
            input: The flattened observation: the model's one input, [1, n] of 32-bit floats.
        """
        return _identity(self._c.call("model_infer", {"name": name, "input": input}, {}))

    def info(self, name: str) -> Dict[str, Any]:
        """One model as model_list answers it, with an ONNX model's manifest and its operator census: the opset of each domain, every operator it uses with how many nodes and which engine runs it, any custom operator domain (never loaded), and the finding a person reads with its offers.

        Scope: read. Plan: free. Since: 3.6.0.
        Arguments:
            name: A model's name in the models folder.
        """
        return _identity(self._c.call("model_info", {"name": name}, {}))

    def install(self, name: str, *, manifest: Optional[Any] = None, onnx_base64: Optional[str] = None, python: Optional[str] = None) -> Dict[str, Any]:
        """Writes a model into the person's models folder - an ONNX model (onnx_base64 with its manifest) or a Python model (python, its source) - where it waits for the person's tick on these exact bytes (Settings > Forecast > Models, Run it) before anything runs it; a model replaced since it was ticked waits again. A name the person's own file holds is never overwritten. Answers the model as model_list does, its consent waiting_for_the_tick.

        Scope: admin. Plan: free. Since: 3.6.0.
        Arguments:
            name: The model's name in the models folder: a folder for an ONNX model, a .py name for a Python one.
            manifest: Its manifest (model_manifest), with the ONNX file.
            onnx_base64: An ONNX model's file, base64.
            python: A Python model's source, declaring one @bentrix.model.
        """
        return _identity(self._c.call("model_install", {"name": name}, {"manifest": manifest, "onnx_base64": onnx_base64, "python": python}))

    def list(self) -> Dict[str, Any]:
        """Every model in the person's models folder: its name, kind (onnx or python), the label its forecasts carry where the manifest says it, its hash, its consent (own - the person's file, no tick needed; waiting_for_the_tick - installed by an agent; ticked), the engine it would run on, and the ids it runs under now. Never where an engine's library is.

        Scope: read. Plan: free. Since: 3.6.0.
        """
        return _identity(self._c.call("model_list", {}, {}))

    def pause(self, model: int, *, paused: Optional[bool] = None) -> Dict[str, Any]:
        """Pauses a running model (it is asked nothing at the closes while paused; its last forecast stays) or resumes it (paused false), as the legend row's Pause does. Answers its state.

        Scope: lab. Plan: free. Since: 3.4.0.
        Arguments:
            paused: For model_pause: true pauses, false resumes.
        """
        return _identity(self._c.call("model_pause", {"model": model}, {"paused": paused}))

    def run_once(self, name: str, bench: str, symbol: str, *, at_ms: Optional[int] = None) -> Dict[str, Any]:
        """Runs a model of the models folder once - consent checked, on the engine the person chose, in a process of its own unless the person keeps the built-in engine inside Bentrix - on the window cut at the last close of its interval at or before at_ms (the workbench's clock when omitted), and puts what it answers as its forecast - or, for a model whose manifest declares outputs (schema 2), each output as output_put puts it - authored model:<name>, stamped with the workbench's clock when it lands. The frame waits for it at most the Time cap per run. Answers the forecast's state (or the outputs put), the anchor, how long the model took and whether that was late.

        Scope: lab. Plan: free. Since: 3.6.0.
        Arguments:
            name: A model's name in the models folder.
            symbol: The market it forecasts, one of the workbench's.
            at_ms: A moment at or before the workbench's clock: the model runs at the last close of its interval by then. Omitted, the clock.
        """
        return _identity(self._c.call("model_run_once", {"name": name, "bench": bench, "symbol": symbol}, {"at_ms": at_ms}))

    def start(self, bench: str, symbol: str, file: str) -> Dict[str, Any]:
        """Starts a model from the person's models folder - a Python file declaring one @bentrix.model, run by the person's own interpreter, or an ONNX model's folder (model_manifest), run by Bentrix's built-in engine - in a process of its own, on a workbench's market: at each close of its interval it is handed the window cut there, and what it answers is put on the chart as its forecast, stamped with the instant it came back (a slow model's forecast arrives late, as a live program's does). Only a file in the models folder starts; its process carries no Bentrix variable. Answers the model's id and state.

        Scope: lab. Plan: free. Since: 3.4.0.
        Arguments:
            bench: The workbench whose closes the model runs at.
            symbol: The market it forecasts, one of the workbench's.
            file: A name in the models folder: a .py declaring one @bentrix.model, or an ONNX model's folder (model.onnx beside its manifest.json, model_manifest).
        """
        return _identity(self._c.call("model_start", {"bench": bench, "symbol": symbol, "file": file}, {}))

    def stop(self, model: int, *, paused: Optional[bool] = None) -> Dict[str, Any]:
        """Ends a model's process; its forecasts already put stay on the workbench until cleared.

        Scope: lab. Plan: free. Since: 3.4.0.
        Arguments:
            paused: For model_pause: true pauses, false resumes.
        """
        return _identity(self._c.call("model_stop", {"model": model}, {"paused": paused}))

    def state(self, model: str) -> Dict[str, Any]:
        """A running model as model_start answered it: its file, workbench, market, state and why it ended, its declaration, its runs, its late answers, its last error and its engine.

        Scope: read. Plan: free. Since: 3.6.0.
        Arguments:
            model: A running model's id, as model_start answered it.
        """
        return _identity(self._c.read_resource("bentrix://model/{model}", {"model": model}, {}))

    def models_state(self) -> Dict[str, Any]:
        """Every model Bentrix is running: its file, workbench, market, state (starting, running, paused, ended and why), what it declared, how many closes it answered, how many past the time cap, and its last error; and the models folder with its .py files.

        Scope: read. Plan: free. Since: 3.4.0.
        """
        return _identity(self._c.read_resource("bentrix://models", {}, {}))

    def models_runs(self, *, after: Optional[str] = None, timeout_ms: int = 30000) -> Iterator[Any]:
        """Each run of a model Bentrix runs, oldest first - a running model's close, model_run_once, an evaluation it drives, a strategy reading it: model (its label), anchor_ms, took_ms, late (past Late is), error, at_ms. next is the count of items read.

        Scope: read. Plan: free. Since: 3.6.0.
            after: the cursor to read since; omitted, only what is new is yielded.
            timeout_ms: how long one wait lasts before it asks again.
        """
        return self._c.watch("bentrix://models/runs{?after}", {}, {}, _identity, after, timeout_ms)


