class _TemplateApi:
    """The `template` capabilities."""

    def __init__(self, client: _Client) -> None:
        self._c = client

    def apply(self, chart: str, *, all_charts: Optional[bool] = None, blank: Optional[bool] = None, name: Optional[str] = None) -> Dict[str, Any]:
        """Applies a saved template — or blank, no studies — to a chart or every chart of its workbench, as the templates menu does; what could not be applied is said, one line each. Answers the chart and those lines.

        Scope: lab. Plan: plus. Since: 1.0.0.
        Arguments:
            all_charts: Onto every chart of the chart's workbench, as the menu's All switch.
            name: The template's name; absent with blank, which takes every study off.
        """
        return _identity(self._c.call("template_apply", {"chart": chart}, {"all_charts": all_charts, "blank": blank, "name": name}))

    def delete(self, name: str, *, confirm: Optional[bool] = None) -> Dict[str, Any]:
        """Deletes a saved template, as its row's x and the confirmation do — only with confirm; without it the answer names what would be deleted. Answers the templates.

        Scope: lab. Plan: plus. Since: 1.0.0.
        Arguments:
            confirm: Without it nothing is deleted and the answer says what would be.
        """
        return _identity(self._c.call("template_delete", {"name": name}, {"confirm": confirm}))

    def rename(self, name: str, to: str) -> Dict[str, Any]:
        """Renames a saved template, as its gear's Rename does. Answers the templates.

        Scope: lab. Plan: plus. Since: 1.0.0.
        """
        return _identity(self._c.call("template_rename", {"name": name, "to": to}, {}))

    def save(self, chart: str, name: str, *, with_type: Optional[bool] = None) -> Dict[str, Any]:
        """Saves a chart's studies — and its type and look with with_type — as a named template, as the templates menu's Save does; a name taken or unusable is refused in its words. Answers the templates.

        Scope: lab. Plan: plus. Since: 1.0.0.
        Arguments:
            chart: The chart whose studies (and, with with_type, type and look) become the template.
            with_type: The chart's type and look saved with its studies.
        """
        return _identity(self._c.call("template_save", {"chart": chart, "name": name}, {"with_type": with_type}))

    def set_default(self, *, clear_all: Optional[bool] = None, interval: Optional[str] = None, name: Optional[str] = None) -> Dict[str, Any]:
        """Makes a template the one a new chart of an interval opens with, or takes the default off an interval or off every interval a template is the default of, as the template gear's choices do. Answers the templates.

        Scope: lab. Plan: plus. Since: 1.0.0.
        Arguments:
            clear_all: Every interval this template is the default of loses it.
            interval: The interval it opens with, as the menu writes it (M1, H4, D1); absent with clear_all.
            name: The template, or absent to make the interval open with none.
        """
        return _identity(self._c.call("template_set_default", {}, {"clear_all": clear_all, "interval": interval, "name": name}))


class _TradeApi:
    """The `trade` capabilities."""

    def __init__(self, client: _Client) -> None:
        self._c = client

    def export_deals(self, bench: str) -> Dict[str, Any]:
        """Writes every deal of the workbench's venue, oldest first, as its History tab lists them, as CSV into the export folder under this agent's name; answers the file's path, uri, rows and bytes.

        Scope: read. Plan: free. Since: 1.0.0.
        """
        return _identity(self._c.call("export_deals", {"bench": bench}, {}))

    def order_close(self, bench: str, ticket: int, *, volume: Optional[float] = None) -> Dict[str, Any]:
        """Closes a position (all of it, or volume lots of it) or cancels a pending order on a laboratory or paper workbench, as the Toolbox's Close does; a close is never refused for being a close. Answers the book. On a real account it goes through the account's agents' mode: proposed in the trade panel for the person's Send (outcome awaiting_person), or under the person's One-click, with real:send, sent as their One-click sends (outcome sent); refused expired past its validity and refused_by_cap past the account's caps.

        Scope: lab. Plan: plus. Since: 1.0.0.
        Arguments:
            volume: Lots to close; absent closes all of it (a pending order is cancelled).
        """
        return _identity(self._c.call("order_close", {"bench": bench, "ticket": ticket}, {"volume": volume}))

    def order_close_all(self, bench: str, *, symbol: Optional[str] = None) -> Dict[str, Any]:
        """Closes every open position on a workbench, or every one of one market, as the trade panel's Close all does; pending orders stay. Answers the book. On a real account it goes through the account's agents' mode: proposed in the trade panel for the person's Send (outcome awaiting_person), or under the person's One-click, with real:send, sent as their One-click sends (outcome sent).

        Scope: lab. Plan: plus. Since: 1.1.0.
        Arguments:
            symbol: One market's positions only; absent closes every position on the workbench.
        """
        return _identity(self._c.call("order_close_all", {"bench": bench}, {"symbol": symbol}))

    def order_market(self, bench: str, symbol: str, side: Literal["buy", "sell"], volume: float, *, sl: Optional[float] = None, tp: Optional[float] = None) -> Dict[str, Any]:
        """Sends a market order on a laboratory or paper workbench through the trade panel's own door; it fills on the workbench's next tick. Refused in the venue's own words where a press would be (a closed market, the stops level, the trade mode). Answers the book and the venue's last answer. On a real account it goes through the account's agents' mode: proposed in the trade panel for the person's Send (outcome awaiting_person), or under the person's One-click, with real:send, sent as their One-click sends (outcome sent); refused expired past its validity and refused_by_cap past the account's caps.

        Scope: lab. Plan: plus. Since: 1.0.0.
        Arguments:
            sl: The stop, a price; absent for none.
            tp: The target, a price; absent for none.
        """
        return _identity(self._c.call("order_market", {"bench": bench, "symbol": symbol, "side": side, "volume": volume}, {"sl": sl, "tp": tp}))

    def order_modify(self, bench: str, ticket: int, sl: float, tp: float, *, price: Optional[float] = None) -> Dict[str, Any]:
        """Sets a position's or a pending order's stop and target (and a pending order's trigger) on a laboratory or paper workbench, as a drag on its chart line does; the venue answers at once. Answers the book. On a real account it goes through the account's agents' mode: proposed in the trade panel for the person's Send (outcome awaiting_person), or under the person's One-click, with real:send, sent as their One-click sends (outcome sent); refused expired past its validity and refused_by_cap past the account's caps.

        Scope: lab. Plan: plus. Since: 1.0.0.
        Arguments:
            ticket: A position's or a pending order's ticket.
            sl: The new stop, a price; 0 removes it.
            tp: The new target, a price; 0 removes it.
            price: A pending order's new trigger; absent leaves it where it is.
        """
        return _identity(self._c.call("order_modify", {"bench": bench, "ticket": ticket, "sl": sl, "tp": tp}, {"price": price}))

    def order_pending(self, bench: str, symbol: str, kind: Literal["buy_limit", "sell_limit", "buy_stop", "sell_stop", "buy_stop_limit", "sell_stop_limit"], price: float, volume: float, *, sl: Optional[float] = None, stop_limit: Optional[float] = None, tp: Optional[float] = None) -> Dict[str, Any]:
        """Places a limit, stop or stop-limit order on a laboratory or paper workbench through the trade panel's own door; the venue answers at once - it rests, or it is refused in its own words (the side rule, the stops level). Answers the book. On a real account it goes through the account's agents' mode: proposed in the trade panel for the person's Send (outcome awaiting_person), or under the person's One-click, with real:send, sent as their One-click sends (outcome sent); refused expired past its validity and refused_by_cap past the account's caps.

        Scope: lab. Plan: plus. Since: 1.0.0.
        Arguments:
            price: The trigger price.
            stop_limit: A stop-limit's limit price; absent for every other kind.
        """
        return _identity(self._c.call("order_pending", {"bench": bench, "symbol": symbol, "kind": kind, "price": price, "volume": volume}, {"sl": sl, "stop_limit": stop_limit, "tp": tp}))

    def order_preview(self, bench: str, symbol: str, side: Literal["buy", "sell"], volume: float) -> Dict[str, Any]:
        """Answers what a market order would cost on a laboratory or paper workbench now, from its venue: the fill price, the margin, the commissions, the spread on this size, the nightly swaps and what one point is worth on one lot. Sends nothing.

        Scope: read. Plan: free. Since: 1.0.0.
        """
        return _identity(self._c.call("order_preview", {"bench": bench, "symbol": symbol, "side": side, "volume": volume}, {}))

    def order_reverse(self, bench: str, ticket: int) -> Dict[str, Any]:
        """Turns a position the other way at the same size, as the trade panel's Reverse does: on a hedging account it is closed and a market order of its size opened the other way; on a netting account one market order of twice its size. Answers the book. On a real account it goes through the account's agents' mode: proposed in the trade panel for the person's Send (outcome awaiting_person), or under the person's One-click, with real:send, sent as their One-click sends (outcome sent); refused expired past its validity and refused_by_cap past the account's caps.

        Scope: lab. Plan: plus. Since: 1.1.0.
        Arguments:
            ticket: The position to turn the other way.
        """
        return _identity(self._c.call("order_reverse", {"bench": bench, "ticket": ticket}, {}))

    def order_trail(self, bench: str, ticket: int, points: float) -> Dict[str, Any]:
        """Arms a trailing stop on a position, the trade panel's own: the stop follows the price at this distance in points, moved by Bentrix while it runs and stopping when Bentrix is shut. Answers the book and the trails armed. On a real account it goes through the account's agents' mode: proposed in the trade panel for the person's Send (outcome awaiting_person), or under the person's One-click, with real:send, armed (outcome sent).

        Scope: lab. Plan: plus. Since: 1.0.0.
        Arguments:
            points: The trail's distance from the price, in the market's points.
        """
        return _identity(self._c.call("order_trail", {"bench": bench, "ticket": ticket, "points": points}, {}))

    def order_untrail(self, bench: str, ticket: int) -> Dict[str, Any]:
        """Disarms a position's trailing stop; the stop stays where the trail last put it. Sends nothing, so on a real account it needs only real. Answers the book and the trails armed.

        Scope: lab. Plan: plus. Since: 1.0.0.
        """
        return _identity(self._c.call("order_untrail", {"bench": bench, "ticket": ticket}, {}))

    def order_validate(self, bench: str, volume: float, *, market: Optional[bool] = None, opens: Optional[float] = None) -> Dict[str, Any]:
        """Answers what an order of this volume would meet on a workbench, and sends and proposes nothing: on a real account its agents' mode (confirm or one_click), whether it would be sent, proposed in the panel's sheet for the person's Send, or refused and why (its validity, the volume cap, the orders and lots of the rolling hour), the caps and what of them is used, whether a proposal already waits, the daily loss cap; on a laboratory or paper workbench that Bentrix's venue answers it at send.

        Scope: lab. Plan: plus. Since: 1.22.0.
        Arguments:
            volume: The lots the order would carry.
            market: A market order (validity of a market order); false for a pending order, a modify or a close.
            opens: The lots it would open: the volume for a new order (the default), 0 for a close or a modify.
        """
        return _identity(self._c.call("order_validate", {"bench": bench, "volume": volume}, {"market": market, "opens": opens}))

    def agent_mode(self, account: str) -> Dict[str, Any]:
        """Answers, read only, a real account's Automations mode for this sitting - confirm or one_click - its caps (lots an order, orders and lots opened an hour), what of them this hour has used, a proposal standing, and whether this agent holds real and real:send. Never sets anything: the mode and the caps are the person's.

        Scope: read. Plan: free. Since: 1.0.0.
        Arguments:
            account: The account's uri, as get_state gives it.
        """
        return _identity(self._c.call("trade_agent_mode", {"account": account}, {}))

    def account(self, home: str, owner: str, bench: str) -> Dict[str, Any]:
        """The workbench's balance, equity, margin, free margin and margin level in its account's currency, as its Toolbox's money row holds them: a laboratory's or paper workbench's own venue (source venue), or on a real account MetaTrader's own figures (source metatrader), read and never stored. A real account's money is answered only to an agent holding real; before MetaTrader has said it there is none.

        Scope: read. Plan: free. Since: 1.1.0.
        Arguments:
            home: `lab` or `account`.
            owner: The laboratory's or the account's id.
        """
        return _identity(self._c.read_resource("bentrix://{home}/{owner}/bench/{bench}/account", {"home": home, "owner": owner, "bench": bench}, {}))

    def book(self, home: str, owner: str, bench: str) -> Dict[str, Any]:
        """The workbench's open positions and pending orders, as its Toolbox's Trade tab holds them, each with its ticket.

        Scope: read. Plan: free. Since: 1.0.0.
        Arguments:
            home: `lab` or `account`.
            owner: The laboratory's or the account's id.
        """
        return _identity(self._c.read_resource("bentrix://{home}/{owner}/bench/{bench}/book", {"home": home, "owner": owner, "bench": bench}, {}))

    def deals(self, home: str, owner: str, bench: str, *, after: Optional[str] = None, timeout_ms: int = 30000) -> Iterator[Any]:
        """Each deal the workbench's venue makes, oldest first, as its History tab lists it: ticket, order, position, market, side, entry, time, price, volume, commission, swap, profit and magic; at most 1000 a page. next is the count of deals read.

        Scope: read. Plan: free. Since: 1.0.0.
            after: the cursor to read since; omitted, only what is new is yielded.
            timeout_ms: how long one wait lasts before it asks again.
        """
        return self._c.watch("bentrix://{home}/{owner}/bench/{bench}/deals{?after}", {"home": home, "owner": owner, "bench": bench}, {}, _identity, after, timeout_ms)


