class _WorkspaceApi:
    """The `workspace` capabilities."""

    def __init__(self, client: _Client) -> None:
        self._c = client

    def app_quit(self) -> _Job[Dict[str, Any]]:
        """Asks the person, on a card in Bentrix's window naming this agent, to close Bentrix; Allow closes it as its Exit does, the workspace written first. Answers a job.

        Scope: admin. Plan: free. Since: 1.0.0.
        """
        return self._c.call_job("app_quit", {}, {}, _identity)

    def area_switch(self, area: Literal["laboratory", "real"]) -> Dict[str, Any]:
        """Switches the window between its two areas, the laboratory and real; each remembers its own last workbench. Answers the area and the workbench now shown.

        Scope: lab. Plan: plus. Since: 1.0.0.
        """
        return _identity(self._c.call("area_switch", {"area": area}, {}))

    def capture_get(self, capture: int, *, without_picture: Optional[bool] = None) -> Dict[str, Any]:
        """Where a capture stands: waiting, failed with the reason, or taken — the picture as a base64 PNG, its size in pixels, the window's pixels per point, and every thing that window drew in that frame (tag, text, rectangle in points; times pixels_per_point is its place in the picture). The last eight are kept.

        Scope: read. Plan: free. Since: 3.2.0.
        Arguments:
            capture: The number screen_capture answered.
            without_picture: Leave the picture out and answer only its size and the record (to measure, or to save a call's weight).
        """
        return _identity(self._c.call("capture_get", {"capture": capture}, {"without_picture": without_picture}))

    def clock_set(self, killzones: bool) -> Dict[str, Any]:
        """Turns the clock's killzones on or off, as its own switch does. Answers the switch.

        Scope: lab. Plan: plus. Since: 1.0.0.
        Arguments:
            killzones: Whether the clock draws the killzones.
        """
        return _identity(self._c.call("clock_set", {"killzones": killzones}, {}))

    def clock_watch(self, timeframe: str, on: bool) -> Dict[str, Any]:
        """Adds an interval's candle countdown to the clock's watchlist, or takes it off, as the clock's own list does. Answers the watchlist.

        Scope: lab. Plan: plus. Since: 1.0.0.
        Arguments:
            timeframe: The interval whose candle countdown the clock shows, as the menu writes it.
        """
        return _identity(self._c.call("clock_watch", {"timeframe": timeframe, "on": on}, {}))

    def dock_set(self, edge: str, *, collapsed: Optional[bool] = None, extent: Optional[float] = None, folded: Optional[bool] = None, section: Optional[int] = None) -> Dict[str, Any]:
        """Folds or unfolds a column of the dock, sets its extent within its floor and ceiling, or collapses or opens one of its sections, as the column's fold, its edge and a section's caret do. Answers the dock.

        Scope: lab. Plan: free. Since: 1.0.0.
        Arguments:
            edge: right, left, top or bottom.
            extent: The column's width (an edge column) or height (a top or bottom one), in points; held within the column's own floor and ceiling.
            folded: The column folded to its strip, or unfolded.
            section: A section of the column, from 0, and whether it is collapsed to its header.
        """
        return _identity(self._c.call("dock_set", {"edge": edge}, {"collapsed": collapsed, "extent": extent, "folded": folded, "section": section}))

    def favourite_set(self, favourite: str, starred: bool) -> Dict[str, Any]:
        """Stars or unstars an interval, an indicator, a chart type, a drawing tool, a cursor or a template, as the stars in their menus do; the bar shows the starred ones. Answers the favourites.

        Scope: lab. Plan: plus. Since: 1.0.0.
        Arguments:
            favourite: The favourite as it is saved: interval.H4, indicator.rsi, charttype.renko, tool.trend_line, cursor.crosshair — or template.<name>.
        """
        return _identity(self._c.call("favourite_set", {"favourite": favourite, "starred": starred}, {}))

    def get_state(self, *, depth: Optional[Literal["benches", "charts"]] = None) -> Dict[str, Any]:
        """Answers the application as the person sees it: the shown area, the selected workbench, every laboratory and real account with its workbenches - each at its own cursor, with its days, tick model, time zone, markets and whether it plays - and, at depth charts, each workbench's chart windows. Every node carries its uri.

        Scope: read. Plan: free. Since: 1.0.0.
        """
        return _identity(self._c.call("get_state", {}, {"depth": depth}))

    def layout_get(self, *, bench: Optional[str] = None) -> Dict[str, Any]:
        """Answers a workbench's chart windows - each one's uri, its rectangle as fractions of the chart area [x0, y0, x1, y1], its place in the stack and its state - and the dock's columns.

        Scope: read. Plan: free. Since: 1.0.0.
        Arguments:
            bench: A workbench's uri; omitted, the one selected.
        """
        return _identity(self._c.call("layout_get", {}, {"bench": bench}))

    def layout_set(self, bench: str, windows: List[WindowPlace]) -> Dict[str, Any]:
        """Places a workbench's chart windows at the rectangles given as fractions of the chart area, as dragging their edges does; a window placed is no longer minimized or maximized. Answers the layout.

        Scope: lab. Plan: free. Since: 1.0.0.
        """
        return _identity(self._c.call("layout_set", {"bench": bench, "windows": windows}, {}))

    def panel_detach(self, panel: str) -> Dict[str, Any]:
        """Takes a docked panel into a window of its own, as its section header's Detach does: marketwatch, trade, clock, toolbox, charttype, indsettings, help, replay, datawindow, symbolinfo or alerts. Answers the dock.

        Scope: lab. Plan: free. Since: 1.0.0.
        Arguments:
            panel: marketwatch, trade, clock, toolbox, charttype, indsettings, help, replay, datawindow, symbolinfo or alerts.
        """
        return _identity(self._c.call("panel_detach", {"panel": panel}, {}))

    def panel_hide(self, panel: Literal["market_watch", "alerts", "strategies", "toolbox", "data_window"]) -> Dict[str, Any]:
        """Hides Market Watch, the Alerts or Strategies panel, the selected workbench's Toolbox or the data window, as their toggles do. Answers whether it is shown.

        Scope: lab. Plan: plus. Since: 1.0.0.
        """
        return _identity(self._c.call("panel_hide", {"panel": panel}, {}))

    def panel_show(self, panel: Literal["market_watch", "alerts", "strategies", "toolbox", "data_window"]) -> Dict[str, Any]:
        """Shows Market Watch, the Alerts or Strategies panel, the selected workbench's Toolbox or the data window, as their toggles do. Answers whether it is shown.

        Scope: lab. Plan: plus. Since: 1.0.0.
        """
        return _identity(self._c.call("panel_show", {"panel": panel}, {}))

    def screen_capture(self, *, holding: Optional[str] = None) -> Dict[str, Any]:
        """Asks the main window, or the window that draws a thing whose tag starts with holding, for a picture of its next frame. Nothing moves the pointer and no window is brought forward. Answers the capture's number; capture_get reads the picture. Refused while a real account's workbench is shown, unless the person gave this agent real.

        Scope: read. Plan: free. Since: 3.2.0.
        Arguments:
            holding: The window whose picture is taken: the one that draws a thing whose tag starts with this (`indsettings.` for an indicator's settings card, `trade.` for the trade panel), as the screen page names its rows. The main window when omitted.
        """
        return _identity(self._c.call("screen_capture", {}, {"holding": holding}))

    def select_bench(self, bench: str, *, leave: Optional[Literal["keep", "pause"]] = None) -> Dict[str, Any]:
        """Selects a workbench, which moves the person's own selection: the window then shows it. A workbench left behind while playing keeps playing or pauses, as leave says. Answers the workbench now shown.

        Scope: lab. Plan: plus. Since: 1.0.0.
        Arguments:
            bench: The workbench's uri, as get_state gives it.
            leave: What becomes of the workbench left behind, if it was playing.
        """
        return _identity(self._c.call("select_bench", {"bench": bench}, {"leave": leave}))

    def update_install_now(self) -> _Job[Dict[str, Any]]:
        """When a release is downloaded and staged, asks the person on a card in Bentrix's window to restart now and install it, as the ready line's Restart now does. Answers a job; refused when nothing is staged.

        Scope: admin. Plan: free. Since: 1.0.0.
        """
        return self._c.call_job("update_install_now", {}, {}, _identity)

    def window_pin(self, window: str, pinned: bool) -> Dict[str, Any]:
        """Puts a window's pin in or out, as the pin on its bar does: a window with its pin in stands over Bentrix's other windows. window is a panel's name or a chart's uri. Answers whether it is pinned.

        Scope: lab. Plan: free. Since: 1.0.0.
        Arguments:
            window: A panel's window (marketwatch, trade, clock, toolbox, charttype, indsettings, help, replay, datawindow, symbolinfo, alerts, downloads, strategies) or a chart's uri.
            pinned: The pin in (the window stands over Bentrix's others) or out.
        """
        return _identity(self._c.call("window_pin", {"window": window, "pinned": pinned}, {}))

    def export(self, bench: str) -> Dict[str, Any]:
        """Answers the document the File menu's Export writes: the workbench's charts, each with its market, interval and whole setup (type, studies, drawings), every saved indicator template, and every alert's market and specification - one JSON object (format bentrix-export) a person keeps as a file and workspace_import reads back.

        Scope: read. Plan: free. Since: 1.14.0.
        Arguments:
            bench: The workbench whose charts are exported, as a bentrix://bench/... uri.
        """
        return _identity(self._c.call("workspace_export", {"bench": bench}, {}))

    def import_(self, bench: str, document: Any) -> Dict[str, Any]:
        """Reads a bentrix-export document onto a workbench as the File menu's Import does: each template saved (under name (imported) when the name is taken, never over one), each chart of a market the workbench holds opened as a new window with its setup, each alert of such a market made anew on it. Answers a line each, done or not and why - a market the workbench does not hold, a part that did not read. A document of a later form is refused.

        Scope: lab. Plan: free. Since: 1.14.0.
        Arguments:
            bench: The workbench the charts open on and the alerts are made on, as a bentrix://bench/... uri.
            document: A document workspace_export answered, or a file the File menu's Export wrote.
        """
        return _identity(self._c.call("workspace_import", {"bench": bench, "document": document}, {}))

    def log(self, program: str, *, lines: Optional[int] = None) -> Dict[str, Any]:
        """The newest lines of the program's own log (bentrix) or of the terminal driver's (driver), oldest first, as the Toolbox's Journal reads them.

        Scope: read. Plan: free. Since: 1.0.0.
        Arguments:
            program: `bentrix` for the program's own log, `driver` for the terminal driver's.
            lines: The newest lines, at most 2000; 200 when omitted.
        """
        return _identity(self._c.read_resource("bentrix://log/{program}{?lines}", {"program": program}, {"lines": lines}))

    def screen(self, *, group: Optional[str] = None, page: Optional[int] = None) -> ScreenPage:
        """Every thing the last frame drew, as data: its tag, the text that reached the screen, whether it can be pressed and whether it is enabled, its window and its rectangle in points. Paged at 2000 rows; group keeps the tags that start with it.

        Scope: read. Plan: free. Since: 1.0.0.
        Arguments:
            group: Only the drawn things whose tag starts with this, such as `pane`, `rail`, `toolbox`, `frame`.
            page: The page, from 0; at most 2000 drawn things a page.
        """
        return ScreenPage.from_dict(self._c.read_resource("bentrix://screen{?group,page}", {}, {"group": group, "page": page}))

    def screen_pages(self, *, group: Optional[str] = None, page: Optional[int] = None) -> Iterator[ScreenPage]:
        """Every page of `screen`, following `next` until it is absent."""
        return self._c.read_pages("bentrix://screen{?group,page}", {}, {"group": group, "page": page}, ScreenPage.from_dict)

    def state(self) -> Dict[str, Any]:
        """The application as the person sees it, as get_state answers at depth charts: the shown area, the selected workbench, every laboratory and real account with its workbenches and their chart windows. Every node carries its uri.

        Scope: read. Plan: free. Since: 1.0.0.
        """
        return _identity(self._c.read_resource("bentrix://workspace", {}, {}))


class _ZoneApi:
    """The `zone` capabilities."""

    def __init__(self, client: _Client) -> None:
        self._c = client

    def bars_in_zone(self, bench: str, symbol: str, timeframe: str, zone: str, *, limit: Optional[int] = None) -> Dict[str, Any]:
        """Answers a workbench's candles of one market and interval read and cut in a time zone of the caller's choosing, without changing what the screen shows: a day opens at that zone's midnight, a week at its Monday, H4 on its grid — folded from the workbench's own finer candles (H1, or M30/M15 for a half- or quarter-hour zone), up to the cursor and never past it. Rows are time_ms (the workbench's own stamps), zone_time (the bar's open in that zone), open, high, low, close, tick_volume; newest limit (200 when omitted, at most 2000), oldest first. An interval the zone does not move is read as it is.

        Scope: read. Plan: free. Since: 3.12.0.
        Arguments:
            bench: The workbench's uri.
            symbol: One of the workbench's markets.
            timeframe: The interval, as the menu writes it (H4, D1, W1…).
            zone: The zone to read and cut in: a code from zones_list, an IANA name, system, or display (the workbench's charts' zone).
            limit: The newest bars kept, 200 when omitted, at most 2000.
        """
        return _identity(self._c.call("bars_in_zone", {"bench": bench, "symbol": symbol, "timeframe": timeframe, "zone": zone}, {"limit": limit}))

    def bench_set_display_zone(self, bench: str, zone: str) -> Dict[str, Any]:
        """Sets the time zone a workbench's charts are read in and their candles cut in, as a press on the clock's charts' face does: every chart of the workbench follows; its venue, strategies and swap keep the workbench's own clock. default puts the workbench's own zone (or its broker's) back. Answers the zone.

        Scope: lab. Plan: free. Since: 3.12.0.
        Arguments:
            bench: The workbench's uri, as get_state gives it.
            zone: A zone's code from zones_list, an IANA name, system (this computer's), or default (the workbench's own zone, or its broker's).
        """
        return _identity(self._c.call("bench_set_display_zone", {"bench": bench, "zone": zone}, {}))

    def chart_set_zone(self, chart: str, zone: str) -> Dict[str, Any]:
        """Sets one chart's own time zone, as its settings' Time zone row does: its times read and its candles cut in it, a preview of that chart alone — the workbench's other charts and the clock as they were. default reads it as its workbench again. Answers the chart's zone.

        Scope: lab. Plan: free. Since: 3.12.0.
        Arguments:
            chart: The chart's uri.
            zone: A zone's code from zones_list, an IANA name, system, or default (as its workbench).
        """
        return _identity(self._c.call("chart_set_zone", {"chart": chart, "zone": zone}, {}))

    def clock_read(self) -> Dict[str, Any]:
        """Answers the clock window as it reads the selected workbench: each clock it shows (market: the broker's or the laboratory's zone; computer: this computer's; charts: the workbench's display zone) with its time, region and offset; the workbench's display zone, chosen or default; and the clock's own settings (which clocks, face, hours, parts, sections, desks, band, glow window, close-together line).

        Scope: read. Plan: free. Since: 3.12.0.
        """
        return _identity(self._c.call("clock_read", {}, {}))

    def clock_settings_set(self, settings: Any) -> Dict[str, Any]:
        """Changes the clock window's own settings, as its gear's window does — the fields given laid over the rest. Answers the settings.

        Scope: lab. Plan: free. Since: 3.12.0.
        Arguments:
            settings: Fields of the clock's settings laid over what they are now (clock_read's settings): market, computer, charts, computer_time (replay_moment | real_now), face (analog | analog_and_digital | digital), hours (h24 | h12), seconds_hand, millis, date, week, zone_line, markets, candles, progress, holidays, desks (a bit each: Sydney 1, Tokyo 2, London 4, New York 8), band, warn (off | s10 | s30 | m1), together.
        """
        return _identity(self._c.call("clock_settings_set", {"settings": settings}, {}))

    def zones_list(self, *, search: Optional[str] = None) -> Dict[str, Any]:
        """Answers every time zone Bentrix offers, in the order its lists show them: system (this computer's), the important ones (UTC, New York close, New York, London, Tokyo, Chicago, Frankfurt, Eastern Europe, Dubai, Singapore, Hong Kong, Sydney), every zone of the IANA database and the fixed offsets — each its code (what the other zone tools take), label, region, offsets across the year and offset now. search narrows them.

        Scope: read. Plan: free. Since: 3.12.0.
        Arguments:
            search: Only the zones whose code or name holds this text (case does not matter).
        """
        return _identity(self._c.call("zones_list", {}, {"search": search}))


